html:
{#- Lab Pull Sheet: the paper sheet the lab fills when pulling an order,
    pre-filled from the Sales Order. Data: mt_dispatch.fulfillment_board.lab_pull_sheet -#}
{%- set ps = lab_pull_sheet(doc) -%}
<style>
.lps { font-family: Arial, Helvetica, sans-serif; color: #000; }
.lps h2 { font-family: Impact, "Arial Black", Arial, sans-serif; font-size: 30px; letter-spacing: .5px;
	margin: 0 0 4px; border-bottom: 3px solid #000; padding-bottom: 4px; font-weight: normal; }
.lps table { width: 100%; border-collapse: collapse; }
.lps .top { margin: 12px 0 4px; width: 100%; border-collapse: collapse; }
.lps .top td.c { padding: 0 10px 8px 0; vertical-align: top; }
.lps .top td.c.last { padding-right: 0; }
.lps .box td.nw { white-space: nowrap; }
.lps .box { width: 100%; border: 1px solid #000; border-collapse: collapse; }
.lps .box td { border: none; padding: 6px 8px; font-size: 13px; height: auto; }
.lps .top { table-layout: fixed; }
.lps .box td.l { background: #d9d9d9; font-weight: 700; font-size: 11px; width: 1%; white-space: nowrap; text-transform: uppercase; }
.print-format .lps .items th, .lps .items th { background: #333 !important; color: #fff !important; font-size: 11px;
	padding: 6px 4px; text-transform: uppercase; border: 1px solid #000 !important; text-align: left; }
.lps .items td { border: 1px solid #000; height: 30px; padding: 3px 5px; font-size: 12px; }
.lps .items td.g { background: #d9d9d9; }
.lps .items { table-layout: fixed; }
.lps .strain { page-break-inside: avoid; margin-top: -1px; }
.lps .items tr.first td { border-top: 2px solid #000; }
.lps .tot { margin-top: 8px; }
.lps .tot .box { width: 400px; margin-left: auto; }
.lps .tot .box td { white-space: nowrap; }
.lps .bot { margin-top: 12px; border: 1px solid #000; }
.lps .bot td { padding: 8px; font-size: 11px; font-weight: 700; background: #d9d9d9; border-right: 1px solid #000; width: 25%; }
.lps .bot td:last-child { border-right: none; }
.lps .notes { border: 1px solid #000; margin-top: 10px; min-height: 70px; padding: 6px 8px; font-size: 11px; }
.lps .notes b { font-weight: 700; }
</style>
<div class="lps">
	<h2>LAB PULL SHEET</h2>
	<table class="top">
		<colgroup><col style="width:28%"><col style="width:32%"><col style="width:40%"></colgroup>
		<tr>
			<td class="c"><table class="box"><tr><td class="l">Date:</td><td class="nw">{{ ps.date }}</td></tr></table></td>
			<td class="c"><table class="box"><tr><td class="l">Delivery date:</td><td class="nw">{{ ps.delivery_date }}</td></tr></table></td>
			<td class="c last"><table class="box"><tr><td class="l">Order #:</td><td class="nw">{{ doc.name }}</td></tr></table></td>
		</tr>
		<tr>
			<td class="c" colspan="2"><table class="box"><tr><td class="l">Client:</td><td>{{ doc.customer_name or doc.customer }}</td></tr></table></td>
			<td class="c last"><table class="box"><tr><td class="l">Type of order:</td><td>{{ ps.order_type }}</td></tr></table></td>
		</tr>
	</table>
	{%- set cols -%}
		<colgroup><col style="width:15%"><col style="width:39%"><col style="width:16%"><col style="width:17%"><col style="width:13%"></colgroup>
	{%- endset %}
	<table class="items">
		{{ cols }}
		<thead>
			<tr>
				<th>New Tag #</th>
				<th>Strain</th>
				<th>Pull (ordered)</th>
				<th>Last 6 #'s of tag</th>
				<th>Weight (g)</th>
			</tr>
		</thead>
	</table>
	{#- One block per strain, kept whole on one page: the strain row, then
	    ps.gap_rows blank rows for the extra tags pulled for it. #}
	{%- for row in ps.rows %}
	<div class="strain">
		<table class="items">
			{{ cols }}
			<tr class="first"><td></td><td><b>{{ row.item_name }}</b></td><td>{{ row.qty }}</td><td></td><td class="g"></td></tr>
			{%- for i in range(ps.gap_rows) %}
			<tr><td></td><td></td><td></td><td></td><td class="g"></td></tr>
			{%- endfor %}
		</table>
	</div>
	{%- endfor %}
	<div class="tot">
		<table class="box"><tr><td class="l">Total weight:</td><td>Ordered {{ ps.total }} · Pulled ______</td></tr></table>
	</div>
	<table class="bot">
		<tr>
			<td>CONVERTED: &#9744;</td>
			<td>TAGS MADE: &#9744;</td>
			<td>INITIALS: ______</td>
			<td>VERIFIED: ______</td>
		</tr>
	</table>
	<div class="notes">
		<b>NOTES:</b>
		{%- if ps.short %} Conversion required for: {{ ps.short | join(", ") }}{% endif %}
	</div>
</div>
